 20→// BenchmarkPostCommit measures the full PostCommit hook execution time.
 21→// This is the baseline before introducing a postCommitCache.
 22→//
 23→// Setup: 1 active session with a shadow branch checkpoint, then a commit
 24→// with the Entire-Checkpoint trailer. PostCommit reads HEAD, finds the session,
 25→// runs condensation (filesOverlapWithContent, CondenseSession, carry-forward).
 26→func BenchmarkPostCommit(b *testing.B) {
 27→	b.Run("SingleSession_Active", benchPostCommitSingleSession(session.PhaseActive))
 28→	b.Run("SingleSession_Idle", benchPostCommitSingleSession(session.PhaseIdle))
 29→	b.Run("MultipleSessions_2", benchPostCommitMultipleSessions(2))
 30→	b.Run("MultipleSessions_3", benchPostCommitMultipleSessions(3))
 31→}
 32→
 33→func benchPostCommitSingleSession(phase session.Phase) func(*testing.B) {
 34→	return func(b *testing.B) {
 35→		for range b.N {
 36→			b.StopTimer()
 37→			dir := benchSetupPostCommitRepo(b, phase, 1)
 38→			b.Chdir(dir)
 39→			paths.ClearWorktreeRootCache()
 40→			b.StartTimer()
 41→
 42→			s := &ManualCommitStrategy{}
 43→			if err := s.PostCommit(context.Background()); err != nil {
 44→				b.Fatalf("PostCommit: %v", err)
 45→			}
 46→		}
 47→	}
 48→}
 49→
 50→func benchPostCommitMultipleSessions(sessionCount int) func(*testing.B) {
 51→	return func(b *testing.B) {
 52→		for range b.N {
 53→			b.StopTimer()
 54→			dir := benchSetupPostCommitRepo(b, session.PhaseActive, sessionCount)
 55→			b.Chdir(dir)
 56→			paths.ClearWorktreeRootCache()
 57→			b.StartTimer()
 58→
 59→			s := &ManualCommitStrategy{}
 60→			if err := s.PostCommit(context.Background()); err != nil {
 61→				b.Fatalf("PostCommit: %v", err)
 62→			}
 63→		}
 64→	}
 65→}
