 67→// benchSetupPostCommitRepo creates a git repo with N sessions that have shadow branch
 68→// checkpoints, then creates a commit with the Entire-Checkpoint trailer.
 69→// Returns the repo directory path, ready for PostCommit() to run.
 70→func benchSetupPostCommitRepo(b *testing.B, phase session.Phase, sessionCount int) string {
 71→	b.Helper()
 72→
 73→	dir := b.TempDir()
 74→	// Resolve symlinks (macOS /var -> /private/var)
 75→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 76→		dir = resolved
 77→	}
 78→
 79→	repo, err := git.PlainInit(dir, false)
 80→	if err != nil {
 81→		b.Fatalf("git init: %v", err)
 82→	}
 83→
 84→	// Configure git user
 85→	cfg, err := repo.Config()
 86→	if err != nil {
 87→		b.Fatalf("config: %v", err)
 88→	}
 89→	cfg.User.Name = "Bench User"
 90→	cfg.User.Email = "bench@example.com"
 91→	if err := repo.SetConfig(cfg); err != nil {
 92→		b.Fatalf("set config: %v", err)
 93→	}
 94→
 95→	// Create initial files and commit
 96→	wt, err := repo.Worktree()
 97→	if err != nil {
 98→		b.Fatalf("worktree: %v", err)
 99→	}
100→
101→	// Create multiple files to make file overlap checks realistic
102→	for i := range 5 {
103→		name := fmt.Sprintf("src/file_%d.go", i)
104→		abs := filepath.Join(dir, name)
105→		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
106→			b.Fatalf("mkdir: %v", err)
107→		}
108→		content := fmt.Sprintf("package main\nfunc f%d() {}\n", i)
109→		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
110→			b.Fatalf("write: %v", err)
111→		}
112→		if _, err := wt.Add(name); err != nil {
113→			b.Fatalf("add: %v", err)
114→		}
115→	}
116→
117→	if _, err := wt.Commit("initial commit", &git.CommitOptions{
118→		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
119→	}); err != nil {
120→		b.Fatalf("commit: %v", err)
121→	}
122→
123→	s := &ManualCommitStrategy{}
124→
125→	// Chdir to repo dir for the entire setup (SaveStep, loadSessionState, etc.
126→	// all depend on paths.WorktreeRoot() which uses cwd). b.Chdir restores
127→	// the original directory when the benchmark function returns.
128→	b.Chdir(dir)
129→	paths.ClearWorktreeRootCache()
130→
131→	// Set up each session with a shadow branch checkpoint
132→	modifiedFiles := []string{"src/file_0.go", "src/file_1.go"}
133→	for i := range sessionCount {
134→		sessionID := fmt.Sprintf("bench-session-%d", i)
135→
136→		// Modify files with agent content
137→		for _, f := range modifiedFiles {
138→			abs := filepath.Join(dir, f)
139→			content := fmt.Sprintf("package main\n// modified by agent session %d\nfunc f() {}\n", i)
140→			if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
141→				b.Fatalf("write: %v", err)
142→			}
143→		}
144→
145→		// Create metadata directory with transcript
146→		metadataDir := ".entire/metadata/" + sessionID
147→		metadataDirAbs := filepath.Join(dir, metadataDir)
148→		if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
149→			b.Fatalf("mkdir: %v", err)
150→		}
151→		transcript := `{"type":"human","message":{"content":"implement feature"}}
152→{"type":"assistant","message":{"content":"I'll implement that for you."}}
153→`
154→		if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
155→			b.Fatalf("write transcript: %v", err)
156→		}
157→
158→		paths.ClearWorktreeRootCache()
159→
160→		if err := s.SaveStep(context.Background(), StepContext{
161→			SessionID:      sessionID,
162→			ModifiedFiles:  modifiedFiles,
163→			NewFiles:       []string{},
164→			DeletedFiles:   []string{},
165→			MetadataDir:    metadataDir,
166→			MetadataDirAbs: metadataDirAbs,
167→			CommitMessage:  "Checkpoint 1",
168→			AuthorName:     "Bench",
169→			AuthorEmail:    "bench@test.com",
170→		}); err != nil {
171→			b.Fatalf("SaveStep: %v", err)
172→		}
173→
174→		// Set the session phase
175→		state, err := s.loadSessionState(context.Background(), sessionID)
176→		if err != nil {
177→			b.Fatalf("load state: %v", err)
178→		}
179→		state.Phase = phase
180→		state.FilesTouched = modifiedFiles
181→		if err := s.saveSessionState(context.Background(), state); err != nil {
182→			b.Fatalf("save state: %v", err)
183→		}
184→	}
185→
186→	// Create the user commit with checkpoint trailer (the commit PostCommit will process)
187→	cpID, err := id.Generate()
188→	if err != nil {
189→		b.Fatalf("generate ID: %v", err)
190→	}
191→
192→	// Modify a file and commit with trailer
193→	testFile := filepath.Join(dir, "src/file_0.go")
194→	if err := os.WriteFile(testFile, []byte("package main\n// modified by agent session 0\nfunc f() {}\n"), 0o644); err != nil {
195→		b.Fatalf("write: %v", err)
196→	}
197→	if _, err := wt.Add("src/file_0.go"); err != nil {
198→		b.Fatalf("add: %v", err)
199→	}
200→
201→	commitMsg := fmt.Sprintf("implement feature\n\n%s: %s\n", trailers.CheckpointTrailerKey, cpID)
202→	if _, err := wt.Commit(commitMsg, &git.CommitOptions{
203→		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
204→	}); err != nil {
205→		b.Fatalf("commit: %v", err)
206→	}
207→
208→	return dir
209→}
