//go:build hookperf

package strategy

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TestCommitHookPerformance measures PrepareCommitMsg + PostCommit execution
// time across different session counts. This reproduces the scenario where a
// user with ~95 sessions experienced 25.5s commit time.
//
// Run: go test -v -run TestCommitHookPerformance -tags hookperf -timeout 10m ./cmd/entire/cli/strategy/
func TestCommitHookPerformance(t *testing.T) {
	scenarios := []struct {
		name    string
		ended   int
		idle    int
		active  int
	}{
		{"10sessions", 8, 1, 1},
		{"50sessions", 43, 6, 1},
		{"100sessions", 88, 11, 1},
		{"200sessions", 180, 19, 1},
	}

	type result struct {
		name       string
		total      int
		setup      time.Duration
		prepare    time.Duration
		postCommit time.Duration
	}
	results := make([]result, 0, len(scenarios))

	for _, sc := range scenarios {
		t.Run(sc.name, func(t *testing.T) {
			setupStart := time.Now()

			dir := initHookPerfRepo(t)
			t.Chdir(dir)
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			createHookPerfSettings(t, dir)
			seedHookPerfSessions(t, dir, sc.ended, sc.idle, sc.active)

			// Stage a file change for the commit
			repo, err := git.PlainOpen(dir)
			if err != nil {
				t.Fatalf("open repo: %v", err)
			}
			wt, err := repo.Worktree()
			if err != nil {
				t.Fatalf("worktree: %v", err)
			}
			testFile := filepath.Join(dir, "src/file_0.go")
			if err := os.WriteFile(testFile, []byte("package main\n// user edit\nfunc f() {}\n"), 0o644); err != nil {
				t.Fatalf("write: %v", err)
			}
			if _, err := wt.Add("src/file_0.go"); err != nil {
				t.Fatalf("add: %v", err)
			}

			setupDur := time.Since(setupStart)
			totalSessions := sc.ended + sc.idle + sc.active

			// --- Time PrepareCommitMsg ---
			// Simulate TTY path (the expensive one) with commit_linking=always
			// so it auto-links without blocking on the TTY prompt.
			t.Setenv("ENTIRE_TEST_TTY", "1")
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			commitMsgFile := filepath.Join(dir, ".git", "COMMIT_EDITMSG")
			if err := os.WriteFile(commitMsgFile, []byte("implement feature\n"), 0o644); err != nil {
				t.Fatalf("write commit msg: %v", err)
			}

			s1 := &ManualCommitStrategy{}
			prepStart := time.Now()
			if err := s1.PrepareCommitMsg(context.Background(), commitMsgFile, "message"); err != nil {
				t.Fatalf("PrepareCommitMsg: %v", err)
			}
			prepDur := time.Since(prepStart)

			// Read back the commit message (should have trailer now)
			msgBytes, err := os.ReadFile(commitMsgFile) //nolint:gosec // test file
			if err != nil {
				t.Fatalf("read commit msg: %v", err)
			}
			commitMsg := string(msgBytes)

			// Verify trailer was added
			if _, found := trailers.ParseCheckpoint(commitMsg); !found {
				t.Log("WARNING: PrepareCommitMsg did not add trailer")
			}

			// Create the actual commit so PostCommit can find the trailer
			if _, err := wt.Commit(commitMsg, &git.CommitOptions{
				Author: &object.Signature{Name: "Perf", Email: "perf@test.com", When: time.Now()},
			}); err != nil {
				t.Fatalf("commit: %v", err)
			}

			// --- Time PostCommit ---
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			s2 := &ManualCommitStrategy{}
			postStart := time.Now()
			if err := s2.PostCommit(context.Background()); err != nil {
				t.Fatalf("PostCommit: %v", err)
			}
			postDur := time.Since(postStart)

			t.Logf("=== %s ===", sc.name)
			t.Logf("  Sessions:         %d (ended=%d, idle=%d, active=%d)", totalSessions, sc.ended, sc.idle, sc.active)
			t.Logf("  Setup:            %s", setupDur.Round(time.Millisecond))
			t.Logf("  PrepareCommitMsg: %s", prepDur.Round(time.Millisecond))
			t.Logf("  PostCommit:       %s", postDur.Round(time.Millisecond))
			t.Logf("  TOTAL HOOKS:      %s", (prepDur + postDur).Round(time.Millisecond))

			results = append(results, result{
				name:       sc.name,
				total:      totalSessions,
				setup:      setupDur,
				prepare:    prepDur,
				postCommit: postDur,
			})
		})
	}

	// Print summary table
	t.Log("")
	t.Log("========== COMMIT HOOK PERFORMANCE SUMMARY ==========")
	t.Logf("%-20s | %8s | %12s | %12s | %12s", "Scenario", "Sessions", "Prepare", "PostCommit", "TOTAL")
	t.Log("-------------------------------------------------------------------------------------")
	for _, r := range results {
		t.Logf("%-20s | %8d | %12s | %12s | %12s",
			r.name,
			r.total,
			r.prepare.Round(time.Millisecond),
			r.postCommit.Round(time.Millisecond),
			(r.prepare + r.postCommit).Round(time.Millisecond),
		)
	}
}

// initHookPerfRepo creates a git repo with an initial commit and source files.
func initHookPerfRepo(t *testing.T) string {
	t.Helper()

	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("git init: %v", err)
	}

	cfg, err := repo.Config()
	if err != nil {
		t.Fatalf("config: %v", err)
	}
	cfg.User.Name = "Perf User"
	cfg.User.Email = "perf@example.com"
	if err := repo.SetConfig(cfg); err != nil {
		t.Fatalf("set config: %v", err)
	}

	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("worktree: %v", err)
	}

	for i := range 5 {
		name := fmt.Sprintf("src/file_%d.go", i)
		abs := filepath.Join(dir, name)
		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
			t.Fatalf("mkdir: %v", err)
		}
		content := fmt.Sprintf("package main\nfunc f%d() {}\n", i)
		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
			t.Fatalf("write: %v", err)
		}
		if _, err := wt.Add(name); err != nil {
			t.Fatalf("add: %v", err)
		}
	}

	if _, err := wt.Commit("initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Perf", Email: "perf@test.com", When: time.Now()},
	}); err != nil {
		t.Fatalf("commit: %v", err)
	}

	return dir
}

// createHookPerfSettings writes .entire/settings.json with commit_linking=always
// so PrepareCommitMsg auto-links without prompting.
func createHookPerfSettings(t *testing.T, dir string) {
	t.Helper()
	entireDir := filepath.Join(dir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		t.Fatalf("mkdir .entire: %v", err)
	}
	settings := `{"enabled": true, "strategy": "manual-commit", "commit_linking": "always"}`
	if err := os.WriteFile(filepath.Join(entireDir, "settings.json"), []byte(settings), 0o644); err != nil {
		t.Fatalf("write settings: %v", err)
	}
}

// seedHookPerfSessions creates session state files with realistic phase distribution.
//
// ENDED sessions: state file with LastCheckpointID set (already condensed).
// IDLE sessions: state file + shadow branch checkpoint via SaveStep.
// ACTIVE sessions: state file + shadow branch checkpoint + live transcript file.
func seedHookPerfSessions(t *testing.T, dir string, ended, idle, active int) {
	t.Helper()

	ctx := context.Background()

	// Get HEAD hash for BaseCommit
	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}
	head, err := repo.Head()
	if err != nil {
		t.Fatalf("head: %v", err)
	}
	baseCommit := head.Hash().String()

	// Get worktree ID (empty string for main worktree)
	worktreeID, err := paths.GetWorktreeID(dir)
	if err != nil {
		t.Fatalf("worktree ID: %v", err)
	}

	// Create state store in .git/entire-sessions/
	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		t.Fatalf("mkdir state dir: %v", err)
	}
	store := session.NewStateStoreWithDir(stateDir)

	modifiedFiles := []string{"src/file_0.go", "src/file_1.go"}

	// --- Seed ENDED sessions ---
	// These have state files with LastCheckpointID but no shadow branch.
	// In listAllSessionStates, they survive cleanup because LastCheckpointID is set.
	// In filterSessionsWithNewContent, they trigger a repo.Reference() lookup
	// for the shadow branch that fails (branch doesn't exist).
	for i := range ended {
		sessionID := fmt.Sprintf("perf-ended-%d", i)
		cpID := mustGenerateCheckpointID(t)
		now := time.Now()

		state := &session.State{
			SessionID:         sessionID,
			BaseCommit:        baseCommit,
			WorktreePath:      dir,
			WorktreeID:        worktreeID,
			Phase:             session.PhaseEnded,
			StartedAt:         now.Add(-time.Duration(i+1) * time.Hour),
			LastCheckpointID:  cpID,
			StepCount:         1,
			FilesTouched:      modifiedFiles,
			LastInteractionTime: &now,
		}
		if err := store.Save(ctx, state); err != nil {
			t.Fatalf("save ended state %d: %v", i, err)
		}
	}

	// --- Seed IDLE sessions ---
	// These have shadow branch checkpoints (via SaveStep) and state files.
	// In filterSessionsWithNewContent, they check the shadow branch transcript
	// against CheckpointTranscriptStart to detect new content.
	s := &ManualCommitStrategy{}
	for i := range idle {
		sessionID := fmt.Sprintf("perf-idle-%d", i)
		seedSessionWithShadowBranch(t, s, dir, sessionID, session.PhaseIdle, modifiedFiles)
	}

	// --- Seed ACTIVE sessions ---
	// These have shadow branch checkpoints + a live transcript file.
	// In filterSessionsWithNewContent, ACTIVE sessions always count as having content.
	for i := range active {
		sessionID := fmt.Sprintf("perf-active-%d", i)
		seedSessionWithShadowBranch(t, s, dir, sessionID, session.PhaseActive, modifiedFiles)

		// Create a live transcript file (simulates agent in progress)
		claudeProjectDir := filepath.Join(dir, ".claude", "projects", "test", "sessions")
		if err := os.MkdirAll(claudeProjectDir, 0o755); err != nil {
			t.Fatalf("mkdir claude sessions: %v", err)
		}
		transcript := `{"type":"human","message":{"content":"implement feature"}}
{"type":"assistant","message":{"content":"I'll implement that for you."}}
{"type":"tool_use","name":"write","input":{"path":"src/file_0.go","content":"package main\n// modified\nfunc f() {}\n"}}
`
		transcriptFile := filepath.Join(claudeProjectDir, sessionID+".jsonl")
		if err := os.WriteFile(transcriptFile, []byte(transcript), 0o644); err != nil {
			t.Fatalf("write live transcript: %v", err)
		}
	}

	// Verify seeded sessions
	states, err := store.List(ctx)
	if err != nil {
		t.Fatalf("list states: %v", err)
	}
	t.Logf("  Seeded %d session state files (expected %d)", len(states), ended+idle+active)
}

// seedSessionWithShadowBranch creates a session with a shadow branch checkpoint
// using SaveStep, then sets the desired phase.
func seedSessionWithShadowBranch(t *testing.T, s *ManualCommitStrategy, dir, sessionID string, phase session.Phase, modifiedFiles []string) {
	t.Helper()
	ctx := context.Background()

	// Modify files with agent content
	for _, f := range modifiedFiles {
		abs := filepath.Join(dir, f)
		content := fmt.Sprintf("package main\n// modified by agent %s\nfunc f() {}\n", sessionID)
		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
			t.Fatalf("write %s: %v", f, err)
		}
	}

	// Create metadata directory with transcript
	metadataDir := ".entire/metadata/" + sessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
		t.Fatalf("mkdir metadata: %v", err)
	}
	transcript := `{"type":"human","message":{"content":"implement feature"}}
{"type":"assistant","message":{"content":"I'll implement that for you."}}
`
	if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
		t.Fatalf("write transcript: %v", err)
	}

	paths.ClearWorktreeRootCache()

	if err := s.SaveStep(ctx, StepContext{
		SessionID:      sessionID,
		ModifiedFiles:  modifiedFiles,
		NewFiles:       []string{},
		DeletedFiles:   []string{},
		MetadataDir:    metadataDir,
		MetadataDirAbs: metadataDirAbs,
		CommitMessage:  "Checkpoint 1",
		AuthorName:     "Perf",
		AuthorEmail:    "perf@test.com",
	}); err != nil {
		t.Fatalf("SaveStep %s: %v", sessionID, err)
	}

	// Set the session phase and files touched
	state, err := s.loadSessionState(ctx, sessionID)
	if err != nil {
		t.Fatalf("load state %s: %v", sessionID, err)
	}
	state.Phase = phase
	state.FilesTouched = modifiedFiles
	if err := s.saveSessionState(ctx, state); err != nil {
		t.Fatalf("save state %s: %v", sessionID, err)
	}
}

func mustGenerateCheckpointID(t *testing.T) id.CheckpointID {
	t.Helper()
	cpID, err := id.Generate()
	if err != nil {
		t.Fatalf("generate checkpoint ID: %v", err)
	}
	return cpID
}

