//go:build hookperf

package strategy

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const hookPerfRepoURL = "https://github.com/entireio/cli.git"

// TestCommitHookPerformance measures PrepareCommitMsg + PostCommit execution
// time across different session counts using a clone of the entireio/cli repo
// so that go-git operates on a realistic object database, packed refs, and
// working tree.
//
// Prerequisites:
//   - GitHub access (gh auth login) for cloning the private repo
//
// Run: go test -v -run TestCommitHookPerformance -tags hookperf -timeout 10m ./cmd/entire/cli/strategy/
func TestCommitHookPerformance(t *testing.T) {
	// Clone once, reuse across scenarios via cheap local clones.
	cacheDir := cloneSourceRepo(t)

	scenarios := []struct {
		name   string
		ended  int
		idle   int
		active int
	}{
		{"10sessions", 8, 1, 1},
		{"50sessions", 43, 6, 1},
		{"100sessions", 88, 11, 1},
		{"200sessions", 180, 19, 1},
	}

	type result struct {
		name       string
		total      int
		clone      time.Duration
		setup      time.Duration
		prepare    time.Duration
		postCommit time.Duration
	}
	results := make([]result, 0, len(scenarios))

	for _, sc := range scenarios {
		t.Run(sc.name, func(t *testing.T) {
			totalSessions := sc.ended + sc.idle + sc.active

			// Local clone from cached source (copies .git objects via hardlinks).
			cloneStart := time.Now()
			dir := localClone(t, cacheDir)
			cloneDur := time.Since(cloneStart)

			setupStart := time.Now()
			t.Chdir(dir)
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			createHookPerfSettings(t, dir)
			seedHookPerfSessions(t, dir, sc.ended, sc.idle, sc.active)

			// Stage a file change for the commit using git CLI
			// (avoids go-git worktree.Add which is slow on large repos).
			testFile := filepath.Join(dir, "main.go")
			if err := os.WriteFile(testFile, []byte("package main\n// user edit\nfunc main() {}\n"), 0o644); err != nil {
				t.Fatalf("write: %v", err)
			}
			gitRun(t, dir, "add", "main.go")

			setupDur := time.Since(setupStart)

			// --- Time PrepareCommitMsg ---
			// Simulate TTY path (the expensive one) with commit_linking=always
			// so it auto-links without blocking on the TTY prompt.
			t.Setenv("ENTIRE_TEST_TTY", "1")
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			commitMsgFile := filepath.Join(dir, ".git", "COMMIT_EDITMSG")
			if err := os.WriteFile(commitMsgFile, []byte("implement feature\n"), 0o644); err != nil {
				t.Fatalf("write commit msg: %v", err)
			}

			s1 := &ManualCommitStrategy{}
			prepStart := time.Now()
			if err := s1.PrepareCommitMsg(context.Background(), commitMsgFile, "message"); err != nil {
				t.Fatalf("PrepareCommitMsg: %v", err)
			}
			prepDur := time.Since(prepStart)

			// Read back the commit message (should have trailer now)
			msgBytes, err := os.ReadFile(commitMsgFile) //nolint:gosec // test file
			if err != nil {
				t.Fatalf("read commit msg: %v", err)
			}
			commitMsg := string(msgBytes)

			// Verify trailer was added
			if _, found := trailers.ParseCheckpoint(commitMsg); !found {
				t.Log("WARNING: PrepareCommitMsg did not add trailer")
			}

			// Create the actual commit so PostCommit can find the trailer.
			// Use git CLI to avoid go-git commit overhead on large repos.
			gitRun(t, dir, "commit", "-m", commitMsg, "--allow-empty-message")

			// --- Time PostCommit ---
			paths.ClearWorktreeRootCache()
			session.ClearGitCommonDirCache()

			s2 := &ManualCommitStrategy{}
			postStart := time.Now()
			if err := s2.PostCommit(context.Background()); err != nil {
				t.Fatalf("PostCommit: %v", err)
			}
			postDur := time.Since(postStart)

			t.Logf("=== %s ===", sc.name)
			t.Logf("  Sessions:         %d (ended=%d, idle=%d, active=%d)", totalSessions, sc.ended, sc.idle, sc.active)
			t.Logf("  Local clone:      %s", cloneDur.Round(time.Millisecond))
			t.Logf("  Setup:            %s", setupDur.Round(time.Millisecond))
			t.Logf("  PrepareCommitMsg: %s", prepDur.Round(time.Millisecond))
			t.Logf("  PostCommit:       %s", postDur.Round(time.Millisecond))
			t.Logf("  TOTAL HOOKS:      %s", (prepDur + postDur).Round(time.Millisecond))

			results = append(results, result{
				name:       sc.name,
				total:      totalSessions,
				clone:      cloneDur,
				setup:      setupDur,
				prepare:    prepDur,
				postCommit: postDur,
			})
		})
	}

	// Print summary table
	t.Log("")
	t.Log("========== COMMIT HOOK PERFORMANCE SUMMARY ==========")
	t.Logf("%-20s | %8s | %12s | %12s | %12s", "Scenario", "Sessions", "Prepare", "PostCommit", "TOTAL")
	t.Log("-------------------------------------------------------------------------------------")
	for _, r := range results {
		t.Logf("%-20s | %8d | %12s | %12s | %12s",
			r.name,
			r.total,
			r.prepare.Round(time.Millisecond),
			r.postCommit.Round(time.Millisecond),
			(r.prepare + r.postCommit).Round(time.Millisecond),
		)
	}
}

// cloneSourceRepo does a one-time clone of entireio/cli into a temp directory.
// Returns the path to use as a local clone source for each scenario.
func cloneSourceRepo(t *testing.T) string {
	t.Helper()

	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	t.Logf("Cloning %s into %s ...", hookPerfRepoURL, dir)
	start := time.Now()

	//nolint:gosec // test-only, URL is a constant
	cmd := exec.Command("git", "clone", "--no-checkout", hookPerfRepoURL, dir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git clone failed: %v\n%s", err, out)
	}
	t.Logf("Source clone completed in %s", time.Since(start).Round(time.Millisecond))

	// Checkout so we have a working tree
	gitRun(t, dir, "checkout", "HEAD")

	return dir
}

// localClone creates a fast local clone from the cached source repo.
// Uses --local which hardlinks .git/objects for near-instant clones.
func localClone(t *testing.T, sourceDir string) string {
	t.Helper()

	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	//nolint:gosec // test-only, sourceDir is from t.TempDir()
	cmd := exec.Command("git", "clone", "--local", sourceDir, dir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("local clone failed: %v\n%s", err, out)
	}

	return dir
}

// gitRun executes a git command in the given directory and fails the test on error.
func gitRun(t *testing.T, dir string, args ...string) {
	t.Helper()
	//nolint:gosec // test-only helper
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
	}
}

